/* P2-Q step 19 — PRS decoder golden-vector test.
 *
 * ORACLE PROVENANCE (no shared-brain rule): every expected byte below was
 * hand-traced from the era PPC in
 * pso-decomp/build/GPOE8P/asm/pso/system/prs.s @ 6b38b5383
 * (prs_decompress__10PrsDecoderFPUcPUcl = 0x8036F5B0, prs_read_control_bit =
 * 0x8036F4DC, prs_read_byte_at = 0x8036F764, prs_next_output_byte = 0x8036F7A8).
 * Nothing here is generated by the C under test.
 *
 * Era format facts the traces rely on:
 *  - control bits LSB-first (8036F51C `clrlwi r3,r3,31`, `srawi` shift);
 *    refetch byte when bits_left (u8, `subi`/`clrlwi.` 8-bit wrap) hits 0.
 *  - literal run: while bit==1 { p=next_out; *p=*src++ }  (8036F5FC)
 *  - selector bit==1 -> far token: size byte, hi byte; `or.`==0 -> END
 *    (8036F650/654); off = (hi<<5) + (size>>3) - 0x2000 (8036F660-668);
 *    size&7 -> +2 else ext: next src byte + 1 (8036F678-684).
 *  - selector bit==0 -> near token: size = 2 + 2*bit + bit (8036F6A4-6AC),
 *    off = byte - 0x100 (8036F6BC).
 *  - off += n (8036F6C0); copy `while(size--)` post-decrement (8036F6EC).
 *  - read_byte_at: flushed > offset STRICT -> dst_history[offset] (8036F768
 *    `cmplw`/`ble`); else window index offset-flushed < window_len or
 *    error=1 (8036F78C), byte reads as 0.
 *  - next_output_byte: window_len >= 0x17FF -> memmove(dst+flushed, window,
 *    0x17FF), flushed += 0x17FF (8036F7C0-7F0).
 *  - epilogue: error -> return -1 (8036F710); else tail-flush, return n.
 */
#include "pso_bringup.h"
#include "pso/system/prs.h"
#include <stdio.h>
#include <string.h>
#include <vector>

static int failures, total;
#define CHECK(cond, ...) do { total++; if (!(cond)) { failures++; \
    printf("FAIL "); printf(__VA_ARGS__); printf("\n"); } \
    else { printf("PASS "); printf(__VA_ARGS__); printf("\n"); } } while (0)

static std::vector<u8> dstbuf(0x20000);

static s32 decode(u8 *out, const std::vector<u8> &s) {
    PrsDecoder d;              /* ctor zeroes flushed/window_len/error */
    return d.prs_decompress(out, const_cast<u8 *>(s.data()), 0);
}

/* Stream builder modelling the era reader's byte order: a control byte is
 * appended lazily when its first bit is consumed, and every src byte follows
 * the control byte under which it is read. Not decoder logic — writer only. */
struct Psb {
    std::vector<u8> out;
    size_t ctrlpos = 0; int bp = 0;
    void bit(int v) {
        if (bp == 0) { ctrlpos = out.size(); out.push_back(0); }
        if (v) out[ctrlpos] |= (u8)(1u << bp);
        if (++bp == 8) bp = 0;
    }
    void byte(u8 b) { out.push_back(b); }
    void lit(u8 b)         { bit(1); byte(b); }
    void rle255_far(u16 n) { bit(0); bit(1); byte(0xF8); byte(0xFF); byte((u8)(n - 1)); }
    void endfar()          { bit(0); bit(1); byte(0x00); byte(0x00); }
};

int main() {
    if (pso_bringup_install() != 0) { fprintf(stderr, "arena install failed\n"); return 2; }
    OSInit();
    CHECK(*(u32 *)pso_g2h(0x80000000u + GUEST_SYSRET_OFF) == 32419584u,
          "sysret: busClock word at arena+0xF8 == 32419584 (TB = bus/4 = 8104896)");
    CHECK(pso_prs_window_base == pso_arena_base + 0x1800,
          "substrate: PRS window pinned at arena+0x1800 (era literal 0x80001800 slot)");

    /* G0: ctrl 0x02 = b0:0 end-run, b1:1 selector(far); src 00 00 -> or==0
     * END at 8036F654. n=0, ret 0. */
    {
        std::vector<u8> s = {0x02, 0x00, 0x00};
        std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
        s32 r = decode(dstbuf.data(), s);
        CHECK(r == 0, "G0 empty stream: ret=%d expect 0", (int)r);
    }
    /* G1: ctrl 0x2F = 1,1,1,1,0,1,0,0: literals A B C D; b4=0 end run;
     * b5=1 far -> 00 00 END. out "ABCD", ret 4. */
    {
        std::vector<u8> s = {0x2F, 'A', 'B', 'C', 'D', 0x00, 0x00};
        std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
        s32 r = decode(dstbuf.data(), s);
        CHECK(r == 4 && memcmp(dstbuf.data(), "ABCD", 4) == 0,
              "G1 literal run: ret=%d out=%.4s", (int)r, (char *)dstbuf.data());
    }
    /* G2: ctrl 0x59 = b0:1 lit 'X'; b1:0 end-run; b2:0 near; a=b3:1 b4:1 ->
     * size=(1<<1)+1+2=5; off byte 0xFF -> -0x100 + n(1) = 0: 5 self-overlap
     * copies, iter k: window_len=k+1 before read of abs k (0>.. false, w-o= k
     * < len) -> reads prior 'X' -> "XXXXXX" n=6; b5:0 end-run, b6:1 far,
     * src 00 00 END (b7 unused). ret 6. */
    {
        std::vector<u8> s = {0x59, 'X', 0xFF, 0x00, 0x00};
        std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
        s32 r = decode(dstbuf.data(), s);
        CHECK(r == 6 && memcmp(dstbuf.data(), "XXXXXX", 6) == 0,
              "G2 near-token overlapping RLE: ret=%d out=%.6s", (int)r, (char *)dstbuf.data());
    }
    /* G3: ctrl 0xAF = bits LSB-first 1,1,1,1,0,1,0,1 (= 0x0F + 0x20 + 0x80):
     * b0..b3 literals ABCD, b4:0 end-run, b5:1 far token:
     * size 0xE3 hi 0xFF -> off = (255<<5)+(0xE3>>3)-0x2000 = 8160+28-8192 = -4,
     * +n(4) = 0; size&7=3 -> 5 copies abs[0..4]: A B C D then abs4 = just
     * written 'A' -> "ABCDABCDA" n=9; top: b6:0 end-run, b7:1 far -> 00 00 END. */
    {
        std::vector<u8> s = {0xAF, 'A', 'B', 'C', 'D', 0xE3, 0xFF, 0x00, 0x00};
        std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
        s32 r = decode(dstbuf.data(), s);
        CHECK(r == 9 && memcmp(dstbuf.data(), "ABCDABCDA", 9) == 0,
              "G3 far-token back-reference: ret=%d out=%.9s", (int)r, (char *)dstbuf.data());

        /* G6: same stream delivered through the DVD shim into the arena. */
        DVDInit();
        DVDFileInfo fi; memset(&fi, 0, sizeof fi);
        bool ok = DVDOpen((char *)"logo_e.prs", &fi);
        CHECK(ok, "G6 DVDOpen(logo_e.prs) -> %d", ok);
        if (ok) {
            u8 *src = pso_arena_base + 0x20000;
            s32 got = DVDReadPrio(&fi, src, (s32)fi.length, 0, 2);
            DVDClose(&fi);
            if (got == (s32)s.size()) {
                u8 *adst = pso_arena_base + 0x10000;
                memset(adst, 0, 64);
                PrsDecoder d;
                s32 r2 = d.prs_decompress(adst, src, 0);
                CHECK(r2 == 9 && memcmp(adst, "ABCDABCDA", 9) == 0,
                      "G6 fake-disc -> arena -> era PRS decode end-to-end: ret=%d out=%.9s",
                      (int)r2, (char *)adst);
            } else CHECK(0, "G6 DVD read got=%d want %zu", got, s.size());
        }
    }
    /* G5: ctrl 0x01 = b0:1 lit 'A'; b1:0 end-run; b2:0 near a=b3:0 b4:0 ->
     * size 2; off byte 0x00 -> -0x100 + n(1) = -255 -> read_byte_at with u32
     * param 0xFFFFFF01: flushed(0) > it false, (0xFFFFFF01-0) >= window_len ->
     * error=1 (8036F78C) both copies; loop head `bne` -> epilogue `li r3,-1`. */
    {
        std::vector<u8> s = {0x01, 'A', 0x00};
        std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
        s32 r = decode(dstbuf.data(), s);
        CHECK(r == -1, "G5 corrupt negative offset -> error: ret=%d expect -1", (int)r);
    }
    /* G4: window-flush boundary. Token layout hand-derived above:
     * literal 'Z' + 24x far-RLE(size=F8/hi=FF/ext=FF -> 256, off=-1+n
     * self-reference) + END. Output 1+24*256 = 6145 'Z', crossing the
     * 0x17FF=6143 flush at output byte 6144: memmove pushes window[0..6142]
     * to dst[0..6142]; overlap reads then hit the STRICT `flushed > offset`
     * dst_history path (8036F770) or window[0] just written -> 'Z' either way. */
    {
        Psb p;
        p.lit('Z');
        for (int t = 0; t < 24; t++) p.rle255_far(256);
        p.endfar();
        std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
        s32 r = decode(dstbuf.data(), p.out);
        bool allZ = (r == 6145);
        for (int i = 0; allZ && i < 6145; i++) allZ = dstbuf[i] == 'Z';
        CHECK(allZ, "G4 window-flush RLE stream (%zu bytes in): ret=%d content=%s",
              p.out.size(), (int)r, allZ ? "6145x'Z'" : "MISMATCH");
    }

    /* roundtrip property: Psb re-implements the format from the trace; the
     * decoder must return the buffer exactly (literal + near/far copy mix). */
    {
        u32 seed = 0xC0FFEEu;
        auto lcg = [&]() { seed = seed * 1103515245u + 12345u; return (seed >> 16) & 0xFF; };
        int rt_fail = 0, worst = -1;
        for (int trial = 0; trial < 64; trial++) {
            size_t n = (size_t)lcg() * 8 + trial;
            std::vector<u8> orig(n);
            if (trial % 2) {           /* runs -> real back-references */
                size_t i = 0;
                while (i < n) { u8 v = (u8)lcg(); size_t k = 1 + lcg() % 300;
                    while (k-- && i < n) orig[i++] = v; }
            } else for (size_t i = 0; i < n; i++) orig[i] = (u8)lcg();
            Psb p;
            for (size_t i = 0; i < n; ) {   /* RLE encode: run = min(same-run,256) */
                size_t j = i + 1;
                while (j < n && orig[j] == orig[i] && j - i < 256) j++;
                p.lit(orig[i]);
                size_t k = j - i - 1;
                while (k > 0) { size_t c = k > 255 ? 255 : k;
                    p.rle255_far((u16)c); k -= c; }
                i = j;
            }
            p.endfar();
            std::fill(dstbuf.begin(), dstbuf.end(), 0xCC);
            s32 r = decode(dstbuf.data(), p.out);
            if (r != (s32)n || memcmp(dstbuf.data(), orig.data(), n) != 0) {
                rt_fail++; if (worst < 0) worst = trial;
            }
        }
        CHECK(rt_fail == 0, "roundtrip property: 64 synthetic RLE streams%s",
              rt_fail ? "" : ", all byte-exact");
        if (rt_fail) printf("  first roundtrip failure: trial %d\n", worst);
    }

    /* substrate smokes (steps 2-4) */
    {
        u32 a = OSGetTick();
        volatile long x = 0; for (; x < 2000000; x++) {}
        u32 b = OSGetTick();
        CHECK((u32)(b - a) > 0, "clock shim: OSGetTick advanced %u -> %u", a, b);
        CHECK(OSTicksToMilliseconds(8104896ull) == 1000,
              "clock shim: 1 timebase second == 1000 ms");
        void *p1 = OSAllocFromHeap(__OSCurrHeap, 0x4560);
        void *p2 = OSAllocFromHeap(__OSCurrHeap, 0x73A0);
        CHECK(p1 && p2 && (u8 *)p2 != (u8 *)p1, "heap: two OSAllocFromHeap distinct blocks");
        OSFreeToHeap(__OSCurrHeap, p1);
        void *p3 = OSAllocFromHeap(__OSCurrHeap, 0x10);
        CHECK(p3 != 0 && OSCheckHeap(__OSCurrHeap) == 2,
              "heap: free+realloc, live count=%ld expect 2", OSCheckHeap(__OSCurrHeap));
        OSFreeToHeap(__OSCurrHeap, p2); OSFreeToHeap(__OSCurrHeap, p3);
        CHECK(OSCheckHeap(__OSCurrHeap) == 0, "heap: balanced free -> 0 live");
    }

    printf("== PRS golden + substrate: %d/%d PASS ==\n", total - failures, total);
    return failures == 0 ? 0 : 1;
}
